import { useRef, useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Download, ChevronLeft, ChevronRight, Play, X, Circle } from "lucide-react";
import pdf from "../assets/abdul.pdf";

const slides = [
  {
    key: "marsad",
    title: "ERP & WooCommerce (Marsad)",
    roleLine: "Front-End Developer – Numerique360 (Dubai, UAE)",
    summary:
      "Built ERP dashboards and WooCommerce-integrated modules for UAE clients using React.js and Next.js. Developed a custom WordPress plugin to expose a Menu REST API endpoint for headless frontend usage. Delivered scalable UI components with filters, pagination, analytics, and performance improvements.",
    bullets: [
      "Developed responsive ERP dashboards for Orders, Products, Categories, Customers, and Analytics.",
      "Integrated WooCommerce REST APIs for real-time data synchronization.",
      "Built a custom WordPress plugin exposing a Menu REST API endpoint for optimized frontend consumption.",
      "Implemented search, filters, pagination, and stable UI states for production usage.",
      "Improved performance with memoization and optimized API usage patterns."
    ],
    videoSrc: "/videos/marsad.mp4",
    posterSrc: "/videos/marsad.jpg"
  },
  {
    key: "swapxe",
    title: "Crypto Dashboard (SwapXe)",
    roleLine: "Front-End Developer – Numerique360 (Dubai, UAE)",
    summary:
      "Developed a secure crypto dashboard with JWT authentication and protected routes. Displayed real-time API results such as wallet and transaction views with a clean, responsive dashboard UI.",
    bullets: [
      "Implemented JWT authentication with secure token handling and route protection.",
      "Integrated APIs to show real-time wallet and transaction-related data.",
      "Built reusable dashboard components and responsive layouts.",
      "Added loading states and error handling for reliable user experience."
    ],
    videoSrc: "/videos/swapxe.mp4",
    posterSrc: "/videos/swapxe.jpg"
  },
  {
    key: "aviation",
    title: "Aviation ERP (Bug Fixing)",
    roleLine: "Front-End Developer – Numerique360 (Dubai, UAE)",
    summary:
      "Worked on an existing aviation ERP system primarily focused on bug fixing and maintenance. Resolved UI and functional issues and improved stability through better error handling and testing support.",
    bullets: [
      "Fixed UI and functional bugs across ERP screens and workflows.",
      "Resolved API integration issues and improved error handling.",
      "Assisted in validating fixes and reducing recurring production issues."
    ],
    videoSrc: "/videos/aviation_erp.mp4",
    posterSrc: "/videos/aviation_erp.jpg"
  },
  {
    key: "blockchain",
    title: "Crypto Exchange (APIs)",
    roleLine: "Front-End Developer – Numerique360 (Dubai, UAE)",
    summary:
      "Implemented real-time crypto price/quote fetching with external APIs and refresh logic. Focused on reliable data display, API error handling, and performance-friendly UI updates.",
    bullets: [
      "Integrated pricing/quote APIs to show real-time market values.",
      "Implemented refresh logic and safe error handling for unstable APIs.",
      "Optimized UI update flow for smoother performance."
    ],
    videoSrc: "/videos/blockchain.mp4",
    posterSrc: "/videos/blockchain.jpg"
  },
  {
    key: "jobbot",
    title: "Automation Platform (Job Bot)",
    roleLine: "Front-End Developer – Numerique360 (Dubai, UAE)",
    summary:
      "Built a full-stack automation platform with a monitoring dashboard to track bot runs and job application progress. Focused on structured UI, status visibility, and reliable execution feedback.",
    bullets: [
      "Built dashboards to monitor bot runs, statuses, and step-level progress.",
      "Implemented structured logs and clear UI feedback for each run.",
      "Designed the system to process one job at a time for stability."
    ],
    videoSrc: "/videos/jobbot.mp4",
    posterSrc: "/videos/jobbot.jpg"
  }
];

export default function WorkExperience() {
  const sliderRef = useRef(null);
  const [showLeft, setShowLeft] = useState(false);
  const [showRight, setShowRight] = useState(true);
  const [hovered, setHovered] = useState(false);
  const [isUserScrolling, setIsUserScrolling] = useState(false);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [selectedVideo, setSelectedVideo] = useState(null);

  // Scroll function
  const scrollSlider = (dir) => {
    const container = sliderRef.current;
    if (!container) return;

    // Use full container width for scroll step since items are 100% wide
    const scrollAmount = container.clientWidth;
    const maxScrollLeft = container.scrollWidth - container.clientWidth;

    const newScroll =
      dir === "next"
        ? Math.min(container.scrollLeft + scrollAmount, maxScrollLeft)
        : Math.max(container.scrollLeft - scrollAmount, 0);

    container.scrollTo({ left: newScroll, behavior: "smooth" });
  };

  const scrollToSlide = (index) => {
    const container = sliderRef.current;
    if (!container) return;
    const scrollAmount = container.clientWidth * index;
    container.scrollTo({ left: scrollAmount, behavior: "smooth" });
  };

  // Show/hide buttons & Track Active Slide
  useEffect(() => {
    const container = sliderRef.current;
    if (!container) return;

    const handleScroll = () => {
      setIsUserScrolling(true);
      const maxScrollLeft = container.scrollWidth - container.clientWidth;
      setShowLeft(container.scrollLeft > 5);
      setShowRight(container.scrollLeft < maxScrollLeft - 5);

      // Calculate active slide index
      const index = Math.round(container.scrollLeft / container.clientWidth);
      setCurrentSlide(index);

      const timeout = setTimeout(() => setIsUserScrolling(false), 100);
      return () => clearTimeout(timeout);
    };

    container.addEventListener("scroll", handleScroll);
    handleScroll();

    return () => container.removeEventListener("scroll", handleScroll);
  }, []);

  // Auto-slide
  useEffect(() => {
    const container = sliderRef.current;
    if (!container) return;
    if (selectedVideo) return; // Don't slide if video is open

    const interval = setInterval(() => {
      if (!hovered && !isUserScrolling) {
        const maxScrollLeft = container.scrollWidth - container.clientWidth;
        const atEnd = container.scrollLeft >= maxScrollLeft - 5;

        if (atEnd) {
          container.scrollTo({ left: 0, behavior: "smooth" });
        } else {
          scrollSlider("next");
        }
      }
    }, 7000);

    return () => clearInterval(interval);
  }, [hovered, isUserScrolling, selectedVideo]);

  // Lock scroll when modal is open
  useEffect(() => {
    document.body.style.overflow = selectedVideo ? "hidden" : "unset";
  }, [selectedVideo]);

  // ESC closes modal
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") setSelectedVideo(null);
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, []);

  return (
    <motion.section
      id="work-experience"
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6 }}
      className="max-w-6xl mx-auto px-4 py-16 bg-white dark:bg-gray-900 rounded-xl shadow-xl overflow-hidden"
    >
      <h2 className="text-3xl md:text-4xl font-bold mb-10 text-center text-gray-900 dark:text-white pt-6">
        Work Experience
      </h2>

      <div
        className="relative"
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
      >
        {/* Left Button (desktop only) */}
        <button
          onClick={() => scrollSlider("prev")}
          className={`absolute left-0 top-1/2 -translate-y-1/2 bg-gray-200 dark:bg-gray-700 p-2 rounded-full z-20 hover:scale-110 transition-opacity duration-300 shadow-md transform -translate-x-2 md:translate-x-2
            ${showLeft || hovered ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"}
            hidden md:inline-flex`}
          aria-label="Previous"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>

        {/* Slider Container */}
        <div
          ref={sliderRef}
          className="
            flex
            overflow-x-auto
            snap-x snap-mandatory
            scrollbar-none
            touch-pan-x
            scroll-smooth
          "
          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }} // hide scrollbar
        >
          {slides.map((current, i) => (
            <div
              key={current.key}
              className="w-full flex-shrink-0 snap-position-center snap-center"
            >
              <div className="w-full h-full flex flex-col lg:flex-row items-center lg:items-start gap-8 px-6 md:px-12 py-8">
                {/* Left: Text */}
                <div className="flex-1 text-center lg:text-left flex flex-col justify-center">
                  <h3 className="text-sm font-bold text-blue-600 uppercase tracking-widest mb-2">
                    {current.roleLine}
                  </h3>

                  <h4 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white mb-4">
                    {current.title}
                  </h4>

                  <p className="text-gray-700 dark:text-gray-300 mb-6 leading-relaxed text-base">
                    {current.summary}
                  </p>

                  <ul className="text-left text-gray-600 dark:text-gray-400 mb-8 space-y-2 list-disc list-inside text-sm md:text-base hidden md:block">
                    {current.bullets.map((item, idx) => (
                      <li key={idx}>{item}</li>
                    ))}
                  </ul>

                  <a
                    href={pdf}
                    download
                    className="inline-flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 transition transform hover:scale-105 font-medium w-fit mx-auto lg:mx-0"
                  >
                    <Download className="w-5 h-5" /> Download Resume
                  </a>
                </div>

                {/* Right: Video Preview */}
                <div className="flex-1 w-full max-w-lg lg:max-w-md flex flex-col justify-center">
                  <div
                    className="relative w-full rounded-xl overflow-hidden shadow-2xl cursor-pointer group bg-black aspect-video transform transition-transform duration-300 hover:scale-105"
                    onClick={() => setSelectedVideo(current.videoSrc)}
                  >
                    <div className="absolute inset-0 bg-black/10 group-hover:bg-black/40 transition-colors duration-300 z-10" />
                    <div className="absolute inset-0 flex items-center justify-center z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                      <div className="bg-white/90 dark:bg-black/80 p-4 rounded-full shadow-xl transform scale-75 group-hover:scale-100 transition-transform duration-300">
                        <Play className="w-8 h-8 text-blue-600 fill-current ml-1" />
                      </div>
                    </div>

                    <video
                      src={current.videoSrc}
                      poster={current.posterSrc}
                      className="w-full h-full object-cover"
                      muted
                      loop
                      playsInline
                      autoPlay
                      preload="metadata"
                    />
                  </div>

                  <p className="text-center text-xs text-gray-500 mt-2">
                    If the video doesn’t play, an MP4 version will be provided.
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Right Button (desktop only) */}
        <button
          onClick={() => scrollSlider("next")}
          className={`absolute right-0 top-1/2 -translate-y-1/2 bg-gray-200 dark:bg-gray-700 p-2 rounded-full z-20 hover:scale-110 transition-opacity duration-300 shadow-md transform translate-x-2 md:-translate-x-2
            ${showRight || hovered ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"}
            hidden md:inline-flex`}
          aria-label="Next"
        >
          <ChevronRight className="w-6 h-6" />
        </button>

        {/* Dots */}
        <div className="flex justify-center gap-3 py-5">
          {slides.map((s, idx) => (
            <button
              key={s.key}
              onClick={() => scrollToSlide(idx)}
              className={`transition-all duration-300 p-1 ${idx === currentSlide
                  ? "text-blue-600 scale-125"
                  : "text-gray-400 dark:text-gray-600 hover:text-gray-600 dark:hover:text-gray-400"
                }`}
              aria-label={`Go to slide ${idx + 1}`}
            >
              <Circle className={`w-3 h-3 ${idx === currentSlide ? "fill-current" : ""}`} />
            </button>
          ))}
        </div>
      </div>

      {/* Video Modal */}
      <AnimatePresence>
        {selectedVideo && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-sm p-4"
            onClick={() => setSelectedVideo(null)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              className="relative w-full max-w-5xl bg-black rounded-2xl overflow-hidden shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setSelectedVideo(null)}
                className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black/70 text-white rounded-full transition-colors z-10"
                aria-label="Close video"
              >
                <X className="w-6 h-6" />
              </button>

              <video
                src={selectedVideo}
                controls
                autoPlay
                className="w-full h-auto max-h-[85vh] object-contain mx-auto"
              >
                Your browser does not support the video tag.
              </video>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.section>
  );
}
